import java.io.*;
import java.util.*;

public class Main {

    static class Reader {
        BufferedReader br;
        StringTokenizer st;

        public Reader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = null;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        Reader r = new Reader(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int divisor = r.nextInt();
        int value = r.nextInt();
        boolean isValid = true;
        while (value > 0) {
            if (value % divisor == 0 || value % divisor - 1 == 0) {
                value /= divisor;
            } else if (value % divisor + 1 == divisor) {
                value++;
            } else {
                isValid = false;
                break;
            }
        }
        pw.println(isValid ? "YES" : "NO");
        pw.flush();
    }
}
